import RNA, random

target = ".(((.(((...(((.(((...))).(((....))).)))...(((.(((....))).(((...))).)))...(((.(((....))).(((...))).)))...))).(((...))).)))..".strip()
assert len(target)==123, len(target)

def get_pairs(s):
    stack=[]
    pairs={}
    for i,c in enumerate(s):
        if c=='(':
            stack.append(i)
        elif c==')':
            j=stack.pop()
            pairs[j]=i
            pairs[i]=j
    return pairs

pairs = get_pairs(target)
n = len(target)
paired = set(pairs.keys())
unpaired = [i for i in range(n) if i not in paired]

random.seed(42)

def random_init():
    seq = [None]*n
    bp_options = [('G','C'),('C','G'),('A','U'),('U','A')]
    weights = [0.4,0.4,0.1,0.1]
    for i in range(n):
        if i in pairs and pairs[i] > i:
            j = pairs[i]
            b1,b2 = random.choices(bp_options, weights=weights)[0]
            seq[i]=b1
            seq[j]=b2
    for i in unpaired:
        seq[i] = random.choice(['A','U','G','C'])
    return seq

def seq_to_str(seq):
    return ''.join(seq)

def fold_and_score(seq_str):
    fc = RNA.fold_compound(seq_str)
    mfe_struct, mfe = fc.mfe()
    return mfe_struct, mfe

def hamming_bp_diff(struct, target):
    return sum(1 for a,b in zip(struct,target) if a!=b)

best = None
best_score = 999999
for trial in range(3000):
    seq = random_init()
    s = seq_to_str(seq)
    struct, mfe = fold_and_score(s)
    d = hamming_bp_diff(struct, target)
    if d < best_score:
        best_score = d
        best = s
        print(trial, d, s)
        if d == 0:
            print("SOLVED at trial", trial)
            break

print("FINAL", best_score)
print(best)

